/* Level overlay code after ui/menus; generated by `decomp overlays stubs`, stubs replaced by C as functions are matched. */
#include "types.h"
#include "rnc/ui/vendor/vendor_item_info.h"
#include "asm.h"

/* For a below 0xE0 true when z is 42..43, else when z is at least 39. */
int FUN_L00_002497f8(int z_range_selector, float x, float y, float z) {
    if (z_range_selector < 0xE0) {
        return z >= 42.0f && z <= 43.0f;
    }
    return z >= 39.0f;
}

typedef struct {
    u8 pad0[0xA];
    s16 label;       /* 0x0A: text id */
    s16 cost_index;  /* 0x0C: row in D_L00_001C40B0 */
    u8 padE[0x1A];
} MenuItem;

typedef struct {
    u8 pad0[0x20];
    MenuItem *items;
} Menu;


extern Menu D_L00_001841F0;
extern char D_L00_0015FE38[];
extern char D_L00_0015FE40[];
extern u8 *get_help_message_text(s32) __asm__("FUN_001fdd10");
extern int sprintf_alt(char *, const char *, ...) __asm__("FUN_00116248");

/* Copies menu item idx's label into out, expanding one %b (the bolt cost)
 * or other % escape. */
void FUN_L00_0024a618(s32 idx, u8 *out) {
    u8 buf[16];
    u8 *label_cursor;
    u8 *substitution_cursor;

    label_cursor = get_help_message_text(D_L00_001841F0.items[idx].label);
    substitution_cursor = buf;
    if (label_cursor == 0) {
        return;
    }
    while (*label_cursor != 0 && *label_cursor != '%') {
        *out++ = *label_cursor++;
    }
    if (*label_cursor == 0) {
        *out = *label_cursor;
        return;
    }
    label_cursor++;
    if (*label_cursor == 'b') {
        sprintf_alt((char *)buf, D_L00_0015FE38,
                    D_L00_001C40B0[D_L00_001841F0.items[idx].cost_index].f0);
    } else {
        sprintf_alt((char *)buf, D_L00_0015FE40);
    }
    label_cursor++;
    while (*substitution_cursor != 0) {
        *out++ = *substitution_cursor++;
    }
    while (*label_cursor != 0) {
        *out++ = *label_cursor++;
    }
    *out = 0;
}
